# ----------------------------------------------------------------------------- main
def main():
    parser = argparse.ArgumentParser(
        description="Convert cell masks to polylines with MobileSAM."
    )
    parser.add_argument(
        "--weights_path", type=str, required=True, help="Path to MobileSAM weights"
    )
    parser.add_argument(
        "--output_path", type=str, required=True, help="Output folder (or .csv file)"
    )
    parser.add_argument(
        "--rgb_path", type=str, required=True, help="Path to the RGB image"
    )
    parser.add_argument(
        "--csv_path", type=str, required=True, help="Path to the metadata csv"
    )
    args = parser.parse_args()

    device = "cuda" if torch.cuda.is_available() else "cpu"
